      "rule_code": "EG-006",
      "title": "High proportion of repetitive template-driven investigations",
      "description": "NLP TF-IDF similarity analysis identified that 19.9% of pairwise investigation descriptions share near-identical phrasing, indicating copy-pasted or checklist boilerplate triage.",
